cc.Class({
    extends: cc.Component,

    properties: {
        roundCount: 10,    // 圈数
        _data:null,
        _callBack:null,      // 完成后回调

        wheel:cc.Node,
        bg: cc.Node,
        board:cc.Node,
        btn_spin:cc.Node,
        spine_btn_spin:sp.Skeleton,
        spine_fire:sp.Skeleton,
        spine_win:sp.Skeleton,
        spine_wheel_bg:sp.Skeleton,
        label_start_prize:cc.Label,
        spine_down:sp.Skeleton,
        spine_icon_arrow:sp.Skeleton,
        switchUis:[cc.Node], // 需要根据类型变换的ui
    },

    _getRotation(index) {
        let ret = -this.roundCount * 360;
        let unitAngle = 360/6;
        let indexsAngle = [
            0,
            -360+unitAngle*1,
            -360+unitAngle*2,
            -360+unitAngle*3,
            -360+unitAngle*4,
            -360+unitAngle*5
        ];
        ret += indexsAngle[index];
        return ret;
    },

    onLoad() {
        this._initListener();
    },

    _initListener() {
        this.btn_spin.on("click", this._onStartWheelHandler.bind(this), this);
    },

    _onStartWheelHandler() {
        this.btn_spin.getComponent(cc.Button).interactable = false
        SlotsFacade.soundMgr.playEffect("spin_button");
        SlotsFacade.dm.reqSubGame({rtype:1});
        // let msg = {"data":{"idx":2,"winCoin":20000,"freeCnt":0},"uid":103265,"c":51,"code":200};

    },

    onSpinWheel(msg){
        if(msg.data) {
            this._data.freeCnt = msg.data.freeCnt;
            this._data.winCoin = msg.data.winCoin;
            this._data.idx = msg.data.idx;
        }
        this._startWheel();
    },

    _reset() {
        this.board.angle = 0;
        this.bg.active = false;
        this.wheel.active = false;
        this.wheel.y = this.wheel.height/2;
        this.spine_btn_spin.node.active = false;
        this.spine_wheel_bg.node.active = false;
        this.spine_win.node.active = false;
        this.spine_fire.active = false;
        this.spine_icon_arrow.node.active = false;
        this.label_start_prize.string = "";
        this._data = {
            wheel_type:0,   // 转盘类型
            freeCnt:0,      // 加次数
            winCoin:0,      // 赢金币
            idx:0
        };
    },

    async _startWheel() {
        this.spine_btn_spin.node.active = false;
        this.spine_fire.node.active = true;
        this.spine_wheel_bg.node.active = true;
        SlotsFacade.soundMgr.playEffect("wheel_act");
        await new Promise((res)=> {
            cc.tween(this.board)
                .to(4, {angle:this._getRotation(this._data.idx-1)}, { easing: 'quartInOut' })
                .call(()=> {
                    this.spine_icon_arrow.node.active = true;
                    if(this._data.winCoin) {
                       SlotsFacade.soundMgr.playEffect("wheel_collect");
                    }else {
                       SlotsFacade.soundMgr.playEffect("wheel_collect");
                    }
                    res();
                })
                .start();
        });

        this.spine_fire.node.active = false;
        this.spine_wheel_bg.node.active = false;
        this.spine_win.node.active = true;
        await SlotsFacade.delayTime(2);
        this._completeWheel();
    },

    /**
     * 旋转完毕
     * @param data
     * @returns {Promise<void>}
     * @private
     */
    async _completeWheel() {
        Global.SlotsSoundMgr.stopBgm();
        if(this._data.winCoin) {
            SlotsFacade.soundMgr.playEffect("jp_collect_popup");
            let vo = SlotsFacade.dm.getGameCfg().mapCfg[SlotsFacade.dm.energyData.currId.toString()];
            await SlotsFacade.popup.showWinWheelGold(this._data.winCoin, vo.type);
        }
        await this.close();
        if(this._callBack) {
            this._callBack({freeCnt:this._data.freeCnt, winCoin:this._data.winCoin});
        }
    },

    _fresh() {
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[SlotsFacade.dm.energyData.currId.toString()];
        this._data.wheel_type = vo.type;
        this.switchUis.forEach(element => {
            element.getComponent("ImgSwitchCmp").setIndex(this._data.wheel_type-1);
        });

        this.label_start_prize.string = Global.FormatNumToComma(SlotsFacade.dm.energyData.startPrice);
    },

    /**
     * 开始 开始转盘流程
     */
    open(cb) {
        this._callBack = cb;
        this.node.active = true;
        this._reset();
        this.btn_spin.getComponent(cc.Button).interactable = true
        this._fresh();

        // 显示背景
        this.bg.active = true;
        this.bg.opacity = 1;
        this.bg.runAction(cc.fadeTo(1, 200));

        // 显示盘
        this.wheel.active = true;
        this.spine_down.node.active = true;
        this.spine_down.setAnimation(0, "animation" + this._data.wheel_type)
        cc.tween(this.wheel)
            .to(0.5, {y:0}, {easing:"backOut"})
            .call(()=>{
                this.spine_down.node.active = false;
                SlotsFacade.soundMgr.playBgm("wheel_bgm");
                cc.vv.gameData.checkAutoPlay(this.btn_spin, this._onStartWheelHandler.bind(this));
            })
            .start();
        SlotsFacade.soundMgr.playEffect("wheel_show");
        this.spine_btn_spin.node.active = true;
        this.spine_btn_spin.setAnimation(0, "animation", true);
    },

    async close() {
        SlotsFacade.soundMgr.playEffect("wheel_disappear");
        return new Promise((res) => {
            // 隐藏背景
            cc.tween(this.bg)
                .to(0.5, {opacity:0})
                .call(()=>{
                    this.bg.active = false;
                })
                .start();

            // 隐藏转盘
            cc.tween(this.wheel)
                .to(0.5, {y:this.wheel.height/2}, {easing:"backIn"})
                .call(()=>{
                    this.wheel.active = false;
                    this.node.active = false;
                    Global.SlotsSoundMgr.playUnLoopBgm('bg_bgm');
                    res();
                })
                .start();
        });
    },
});
