let CollectGameMap = cc.Class({
    extends: cc.Component,

    properties: {
        callBack:null,

        _mapWheel:null,

        map_game_node:null,
        bg:null,
        btn_close:null,
        scrollView:null,
        map_flag:null,
        mapItems:[],

        _wheelResp:null, // mapWheel结果
    },

    onLoad() {
        this._initView();
        this._initListener();
    },

    _initView() {
        this.map_game_node = this.node;
        this._mapWheel = this.map_game_node.getChildByName("map_wheel_node").getComponent("Interstellar_MapWheel");
        this.bg = this.map_game_node.getChildByName("bg");
        this.btn_close = this.map_game_node.getChildByName("btn_close").getComponent(cc.Button);
        this.scrollView = this.map_game_node.getChildByName("scrollview").getComponent(cc.ScrollView);
        this.map_flag = this.scrollView.content.getChildByName("map_flag");
        this.mapItems = [];
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        for(let i=1; i<=100; i++) {
            let item = this.scrollView.content.getChildByName("item_" + i);
            item["id"] = i;
            let vo = mapCfg[i.toString()];
            let spineName = "";
            if(vo.type == 1) {
                spineName = "animation1_1";
            }else if(vo.type == 2) {
                spineName = "animation2_1";
            }
            if(spineName) {
                item.getChildByName("spine").getComponent(sp.Skeleton).setAnimation(0, spineName, false);            
            }
            if(vo.type == 3) {
                cc.find("step/label", item).getComponent(cc.Label).string = i;
            }else {
                item.getChildByName("label_step").getComponent(cc.Label).string = i;
            }
            this.mapItems.push(item);
        }
        this._reset();
    },

    _initListener() {
        this.btn_close.node.on("click", this._onBtnCloseHandler.bind(this), this);
    },

    /**
     * 显示关闭按钮
     * @returns {Promise<unknown>}
     * @private
     */
    _showCloseBtn() {
        return new Promise((res)=> {
            this.btn_close.node.active = true;
            this.btn_close.node.scale = 0;
            this.btn_close.interactable = true;
            this.btn_close.node.getChildByName("spine").active = true;
            cc.tween(this.btn_close.node)
                .to(0.3, {scale:1}, {easing:"backOut"})
                .call(()=>{
                    cc.vv.gameData.checkAutoPlay(this.btn_close.node, this._onBtnCloseHandler.bind(this));
                    res();
                })
                .start();
        });
    },

    async _onBtnCloseHandler() {
        this.btn_close.interactable = false;
        this.btn_close.node.getChildByName("spine").active = false;
        this.btn_close.node.stopAllActions()
        cc.tween(this.btn_close.node)
            .to(0.3, {scale:0}, {easing:"backIn"})
            .call(()=>{
                this.exitMap(this._wheelResp);
            })
            .start();
    },

    /**
     * 退出
     */
    exitMap(data) {
        SlotsFacade.soundMgr.playEffect("map_close");
        let svNode = this.scrollView.node;
        cc.tween(svNode)
            .to(0.3, {y:svNode.height}, {easing:"cubicOut"})
            .call(()=>{
                this._reset();
                if(this.callBack) {
                    this.callBack(data);
                    this.callBack = null;
                }
            })
            .start();
    },

    /**
     * 进入
     * @param isView 是否是查看
     * @param cb
     * @returns {Promise<void>}
     */
    async enterMap(isView, cb) {
        SlotsFacade.soundMgr.playEffect("map_show");
        this.callBack = cb;
        this._wheelResp = null;
        this.map_game_node.active = true;
        this.bg.active = true;
        let data = SlotsFacade.dm.energyData;
        let currIndex = data.currId;
        if(!isView && data.state > 0) {
            currIndex -= 1;
        }
        this._freshMap(currIndex);

        if(currIndex > 0) {
            let item = this.mapItems[currIndex-1];
            this.scrollView.scrollToOffset(cc.v2(0, Math.abs(item.y) - this.scrollView.node.height/2));
        }else {
            this.scrollView.scrollToBottom();
        }
        await this._scrollViewShow();
        if (isView) {
            this._showCloseBtn();
        }else {
            await this._moveMapFlag(data.currId);
            let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
            let vo = mapCfg[data.currId];
            if(vo.type < 3) {
                let respData = await new Promise((res)=> {
                    this._mapWheel.open((resp)=>{res(resp)});
                });
                if(respData.freeCnt) {
                    await this._addHouseFreeCnt(data.currId);
                    SlotsFacade.dm.energyData.nextSpinCount += 1;
                }
                this._wheelResp = {winCoin:respData.winCoin};
                this._showCloseBtn();
                // this.exitMap();
            }else {
                this.exitMap({freeCnt:vo.freeCnt});
            }
        }
    },

    /**
     * 加房子的免费次数
     * @returns {Promise<unknown>}
     * @private
     */
    async _addHouseFreeCnt(currIndex) {
        SlotsFacade.soundMgr.playEffect("add");
        return new Promise(res=>{
            let item = this._findNextHouse(currIndex);
            if(item) {
                item.getChildByName("icon_free_cnt").getComponent("ImgSwitchCmp").setIndex(SlotsFacade.dm.energyData.nextSpinCount+1-5);
                let spine = cc.find("icon_free_cnt/spine_free_count_change", item).getComponent(sp.Skeleton);
                spine.node.active = true;
                spine.setAnimation(0, "animation", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    res();
                })
            }else {
                res();
            }
        });
    },

    /**
     * 查找下一个house节点
     * @param currIndex
     * @returns {cc.Node|null}
     * @private
     */
    _findNextHouse(currIndex) {
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        for(let i=currIndex+1; i<=100; i++) {
            let vo = mapCfg[i];
            if(vo.type == 3) {
                return this.mapItems[i-1];
            }
        }
        return null;
    },

    /**
     * 移动地图标记
     * @param toIdx
     * @private
     */
    async _moveMapFlag(toIdx) {
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[toIdx.toString()];
        let item = this.mapItems[toIdx-1];
        // 移动
        await new Promise((res)=> {
            let pos = item.getChildByName("pos");
            cc.tween(this.map_flag)
                .to(1, {x:item.x+pos.x, y:item.y+pos.y})
                .call(()=>{
                    this.map_flag.scaleX = vo.dockerDir || 1;
                    res();
                })
                .start();
        });

        // 播放动画
        await new Promise((res)=> {
            let animationName = "";
            if(vo.type == 1) {
                animationName = "animation1";
                SlotsFacade.soundMgr.playEffect("move");
            }else if(vo.type == 2) {
                animationName = "animation2";
                SlotsFacade.soundMgr.playEffect("move");
            }else if(vo.type == 3) {
                animationName = "animation" + (vo.slot.cnt-1);
                SlotsFacade.soundMgr.playEffect("move2");
            }
            let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, animationName, false)
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                if(vo.type == 3) {
                    spine.node.active = false;
                }
                res();
            });
        });
    },

    _freshMap(currIndex) {
        for(let i=1; i<=currIndex; i++) {
            this._markItemCmp(i);
        }
        if(currIndex > 0) {
            let item = this.mapItems[currIndex-1];
            let pos = item.getChildByName("pos");
            this.map_flag.x = item.x + pos.x;
            this.map_flag.y = item.y + pos.y;
            let vo = SlotsFacade.dm.getGameCfg().mapCfg[currIndex.toString()];
            this.map_flag.scaleX = vo.dockerDir || 1;
            item = this._findNextHouse(currIndex);
            item.getChildByName("icon_free_cnt").getComponent("ImgSwitchCmp").setIndex(SlotsFacade.dm.energyData.nextSpinCount-5);
        }
    },

    /**
     * 标记完成
     */
    _markItemCmp(index) {
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[index.toString()];
        let item = this.mapItems[index-1];
        let color = new cc.Color().fromHEX("#898989");
        item.color = color;
        if(vo.type == 3) {
            item.getChildByName("step").color = color;
            cc.find("step/label", item).color = color;
        }else {
            item.getChildByName("label_step").color = color;
        }
        if(vo.type == 3) {
            item.getChildByName("icon_free_cnt").active = false;
        } else {
            let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
            spine.node.color = color;
            spine.node.active = true;
        }
    },

    /**
     * map显示
     * @returns {Promise<unknown>}
     * @private
     */
    _scrollViewShow() {
        return new Promise((res)=> {
            let svNode = this.scrollView.node;
            svNode.active = true;
            cc.tween(svNode)
                .to(0.5, {y:0}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        });
    },

    /**
     * 重置
     */
    _reset() {
        this.bg.active = false;
        this.scrollView.node.active = false;
        this.scrollView.node.y = this.scrollView.node.height/2;
        this.btn_close.node.active = false;
        this.map_game_node.active = false;
    },
});
