
/**
 * 收集进度
 * @class BeerHall_CollectProgress
 */
cc.Class({
    extends: cc.Component,

    properties: {
        icon_energy:cc.Node,        // 能量收集图标
        btn_enter: cc.Node,         // 进入收集游戏按钮节点
        progressBar: cc.Node,       // 进度条节点
        spine_collect_lock:sp.Skeleton, // 能量条状态spine动画
        spine_full: sp.Skeleton,    // 集满能量条，能量条上的动画
        collect_track_particle:cc.Node, // 能量收集轨道粒子动画

        _isOpen:false,   // 是否打开收集
    },

    onLoad() {
        this._initListener();
    },

    start() {
        this.scheduleOnce(()=>{
            this._init();
        });
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);

        this.btn_enter.on(cc.Node.EventType.TOUCH_END, this._onEnterHandler.bind(this), this);
        this.progressBar.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(!this._isOpen) {
                this._openCollect();
            }
        }, this);
    },

    _init() {
        this.setProgress(SlotsFacade.dm.getCollectPercent());
        this.updateTailSpine();
        this.showCollect(true);
    },

    _onEnterHandler() {
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("btn_click");
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.map.enterMap(true, ()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        });
    },

    updateTailSpine() {
        let nextId = SlotsFacade.dm.energyData.nextId;
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[nextId.toString()];
        if(vo) {
            let spine = this.btn_enter.getChildByName("spine").getComponent(sp.Skeleton);
            let spineName = vo.iconSpineName;
            spine.setAnimation(0, spineName, true);
            // if(spineName == "animation3") {
            //     spine.node.y = 18;
            // }else if(spineName == "animation4") {
            //     spine.node.y = 26;
            // }else if(spineName == "animation5") {
            //     spine.node.y = 36;
            // }else {
            //     spine.node.y = 0;
            // }

        }else {
            console.log("#Err#collectProgress#updateTailSpine", nextId);
        }
    },

    /**
     * 打开收集
     */
    _openCollect() {
        // 如果已经打开收集 返回
        if(this._isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy(globalPosArr, percent) {
        SlotsFacade.soundMgr.playEffect("map_collect");
        let endPos = this.icon_energy.getPosition();
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = this.node.convertToNodeSpaceAR(v);
            let lz = cc.instantiate(this.collect_track_particle);
            lz.parent = this.node;
            lz.x = pos.x;
            lz.y = pos.y;
            lz.active = true;
            let p = lz.getComponent(cc.ParticleSystem);
            p.resetSystem();
            promiseArr.push(new Promise(res=>{
                cc.tween(lz)
                    .to(0.5, {x:endPos.x, y:endPos.y})
                    .call(()=> {
                        lz.removeFromParent();
                        res();
                    })
                    .start();
            }));
        });
        await Promise.all(promiseArr);
        this._playHeadSpine();
        this.setProgress(percent, true);
    },

    _playHeadSpine() {
        let spine = this.icon_energy.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, "animation", false);
    },

    /**
     * 显示收集界面
     * @param isInit
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(!this._isOpen) {
                this.spine_collect_lock.node.active = true;
                SlotsFacade.soundMgr.playEffect("collect_unlock");
                this.spine_collect_lock.setAnimation(0, "animation2", false);
            }
        }else {
            if(isInit) {
                this.spine_collect_lock.node.active = true;
                this.spine_collect_lock.setAnimation(0, "animation1", false);
            }else {
                if(this._isOpen) {
                    this.spine_collect_lock.node.active = true;
                    SlotsFacade.soundMgr.playEffect("collect_lock");
                    this.spine_collect_lock.setAnimation(0, "animation1", false);
                }
            }
        }
        this._isOpen = boo;
    },

    /**
     * 播放收集完成动画
     */
    async playCollectComplete() {
        this.spine_full.node.active = true;
        SlotsFacade.soundMgr.playEffect("map_full");
        await new Promise(res=>{
            this.spine_full.setAnimation(0, "animation3", false);
            this.spine_full.setCompleteListener(()=>{
                this.spine_full.setCompleteListener(null);
                res();
            });
        });
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent, needTransform) {
        let w = this.progressBar.width;
        let toX = -w + percent * w;
        let spine_progress = this.progressBar.getChildByName("bar");
        let colectEffect = cc.find("spine",spine_progress)
        colectEffect.active = true
        colectEffect.getComponent(sp.Skeleton).setCompleteListener(()=>{
            colectEffect.active = false
            colectEffect.getComponent(sp.Skeleton).setCompleteListener(null)
        })
        if(needTransform) {
            cc.tween(spine_progress).to(0.5, {x:toX}).start();
        }else {
            spine_progress.x = toX;
        }
    },

    setEnterEnable(boo) {
        this.btn_enter.getComponent(cc.Button).enabled =boo;
    }
});
