cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        isEpic:false,
        _nodeScale:1,
    },

    StartMove:function(){
        this._super();
        this._data = 0;
        this.showCoin();
    },

    ShowById:function(id,data){
        this._super(id,data);
        this.showColor();
    },

    showCoin() {
        if(this._data > 0) {
            let coin = this._data;
            let txt = cc.find("label_coin",this.node);
            txt.active = coin > 0;
            if(coin > 0) {   
                txt.getComponent(cc.Label).string = Global.formatNumShort(coin);
            }
        }else {
            let txt = cc.find("label_coin",this.node);
            txt.active = false;
        }
    },

    showColor() {
        if(this.isEpic && this._showNode) {
            if(this.GetShowId() == cc.vv.gameData.getGameCfg().bonusId) {
                this._showNode.color = new cc.Color().fromHEX("#FFFFFF");
            }else {
                this._showNode.color = new cc.Color().fromHEX("#3E3E3E");
            }
        }
    },

    //显示随机符号
    ShowRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols.length)
        let randVal = cfg.randomSymbols[randIdx-1]
        let data = 0;
        if(randVal == cfg.bonusId) {
            data = Global.random(0, 10) * SlotsFacade.dm.GetTotalBet();
        }
        this.ShowById(randVal, data);
    },

    showBonusSymol(id,data){
        this._id = id
        this._data = data
        this._state = "normal";
        let cfg = SlotsFacade.dm.getGameCfg();
        if(this._showNode){
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        let topShowNode = cc.find("bonus",aniNode);
        topShowNode.active = true
        
        let zIndex = 500;
        aniNode.zIndex = zIndex - this._symbolIdx + this._reelIdx*10;

        let content_node = topShowNode.getChildByName("content_node");
        content_node.active = true;
        if(id == cfg.scatterId) {
            content_node.getChildByName("epick_icon").active = true;
        }else {
            if(this._data > 0){
                let label = content_node.getChildByName("label");
                label.active = true;
                label.getComponent(cc.Label).string = Global.formatNumShort(this._data);
            }
        }
        this.showColor();
    },

    playBonusSymbol() {
        let id = this._id
        let cfg = SlotsFacade.dm.getGameCfg();
        if(id != cfg.scatterId && id != cfg.bonusId) {
            return;
        }
        if(id == cfg.bonusId && this._data < 1) {
            return;
        }

        // this._state = "win"; //todo check
        if(this._showNode){
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        let topShowNode = cc.find("bonus",aniNode);
        topShowNode.active = true
        
        let zIndex = 500;
        aniNode.zIndex = zIndex - this._symbolIdx + this._reelIdx*10;
        SlotsFacade.soundMgr.playEffect("symbol_bonus");
        //图标光效动画
        let effect = topShowNode.getChildByName("effect").getComponent(sp.Skeleton);
        effect.node.active = true;
        effect.setAnimation(0, "animation1", false);
        effect.addAnimation(0, "animation2", true);
        //转动图标动画
        let reel_ani = topShowNode.getChildByName("reel_ani");
        reel_ani.active = true;
        reel_ani.getComponent(cc.Animation).play("symbol_reel_ani");

        let content_node = topShowNode.getChildByName("content_node");
        content_node.active = true;
        content_node.scale = 0.6;
        if(id == cfg.scatterId) {
            content_node.getChildByName("epick_icon").active = true;
        }else {
            let label = content_node.getChildByName("label");
            label.active = true;
            label.getComponent(cc.Label).string = Global.formatNumShort(this._data);
        }

        // 节点动画
        cc.tween(content_node)
            .to(0.3, {scale:1.3})
            .to(0.1, {scale:1})
            // .delay(0.4)
            .call(()=>{
                // let content_node = topShowNode.getChildByName("content_node");
                // content_node.active = true;
                // content_node.scale = 0;
                // 判断显示epick图标还是金币
                // if(id == cfg.scatterId) {
                //     content_node.getChildByName("epick_icon").active = true;
                // }else {
                //     let label = content_node.getChildByName("label");
                //     label.active = true;
                //     label.getComponent(cc.Label).string = Global.formatNumShort(this._data);
                // }
                // // 内容节点动画
                // cc.tween(content_node)
                //     .to(0.3, {scale:1}, {easing:"backOut"})
                //     .call(()=>{
                //         reel_ani.active = false;
                //         effect.node.active = false;
                //     })
                //     .start();

                reel_ani.active = false;
                if(!this.isEpic){
                    if(id == cfg.scatterId) {
                        effect.node.active = false;
                    }else{
                        effect.setAnimation(0, "animation4", true);
                    }
                }else{
                    effect.node.active = false;
                }
            })
            .start();
    },

    playBonusRightNow() {
        let id = this._id
        let cfg = SlotsFacade.dm.getGameCfg();
        if(id != cfg.scatterId && id != cfg.bonusId) {
            return;
        }
        if(id == cfg.bonusId && this._data < 1) {
            return;
        }
        
        if(this._showNode){
            this._showNode.active = false
        }

        // this._state = "win"; //todo check
        if(this._showNode){
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        let topShowNode = cc.find("bonus",aniNode);
        topShowNode.active = true
        
        let zIndex = 500;
        aniNode.zIndex = zIndex - this._symbolIdx + this._reelIdx*10;
        SlotsFacade.soundMgr.playEffect("symbol_bonus");
        //图标光效动画
        let effect = topShowNode.getChildByName("effect").getComponent(sp.Skeleton);
        effect.node.active = true;
        effect.setAnimation(0, "animation1", false);
        effect.addAnimation(0, "animation2", true);
        let content_node = topShowNode.getChildByName("content_node");
        content_node.active = true;
        content_node.scale = 0;
        // 判断显示epick图标还是金币
        if(id == cfg.scatterId) {
            content_node.getChildByName("epick_icon").active = true;
        }else {
            let label = content_node.getChildByName("label");
            label.active = true;
            label.getComponent(cc.Label).string = Global.formatNumShort(this._data);
        }
        // 内容节点动画
        cc.tween(content_node)
        .to(0.3, {scale:1}, {easing:"backOut"})
        .call(()=>{
            if(!this.isEpic){
                if(id == cfg.scatterId) {
                    effect.node.active = false;
                }else{
                    effect.setAnimation(0, "animation4", true);
                }
            }else{
                effect.node.active = false;
            }
        })
        .start();
        // 节点动画
        cc.tween(topShowNode)
            .to(0.15, {scale:1.2})
            .to(0.25, {scale:1})
            .call(()=>{
            })
            .start();
    },

    playWinFlash () {
        let id = this._id
        let cfg = SlotsFacade.dm.getGameCfg();
        if(id != cfg.scatterId && id != cfg.bonusId) {
            return;
        }
        if(id == cfg.bonusId && this._data < 1) {
            return;
        }

        if(this._showNode){
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        let topShowNode = cc.find("bonus",aniNode);
        topShowNode.active = true

        let spineFlash = cc.find("spine_flash", topShowNode);
        spineFlash.active = true;
        spineFlash.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        spineFlash.getComponent(sp.Skeleton).setCompleteListener(()=>{
            spineFlash.getComponent(sp.Skeleton).setCompleteListener(null);
            spineFlash.active = false;
        });
    },

});
