    /**
     * 开始bonus game对话框
     */
    async showStartBonus(cbHandler) {
        Global.SlotsSoundMgr.stopBgm();
        SlotsFacade.soundMgr.playEffect("dialog_trigger_respin");
        this.showBgDark(true);
        let panel = this.node.getChildByName("panel_bonus_start");
        panel.active = true;
        panel.scale = 1;
        let okBtn = panel.getChildByName("btn_ok");
        okBtn.active = false;

        let spine = panel.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, "animation1", false);
        spine.addAnimation(0, "animation2", true);
        spine.setCompleteListener(()=>{
            okBtn.active = true;
            let handler = ()=>{
                okBtn.stopAllActions();
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBgDark(false);
                        panel.active = false;
                        SlotsFacade.soundMgr.playEffect("popup_out");
                        if(cbHandler) {
                            cbHandler();
                        }
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
            spine.setCompleteListener(null)
        })
    },
