/**
 * 卷轴控制单元
 */



cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        handler:null,
        reelScale : 1,
    },

    onLoad() {
        this._super();
        this.isLoaded = true;
        if(this._nCount) {
            this.Init(this._reelIdx, this._nCount, this._topAniNode);
        }
    },

    onDestroy() {
        this.handler = null;
    },

    Init:function(idx,nCount, node){
        this._reelIdx = idx;
        this._nCount = nCount;
        this._symbols = [];
        this._topAniNode = node;
        this._cfg = cc.vv.gameData.getGameCfg();
        if(this.isLoaded) {
            this.LoadSymbols();
            this.ShowAntiEffect(false);
        }
    },

    CreateOneSymbol:function(){
        this._super();
        let symbol = this._symbols[this._symbols.length-1];
        symbol.node.scale = this.reelScale;
        symbol.isEpic = true;
        symbol._nodeScale = this.reelScale
        symbol.showColor();
    },

    // GetSymbolPosByRow:function(row){
    //     // let cfg = cc.vv.gameData.getGameCfg()
    //     // return cc.v2(0,(row+0.5)*cfg.symbolSize.height*this.reelScale);
    //     return cc.v2(0,(row+0.5)*80);
    // },
    
    setHandler(handler) {
        this.handler = handler;
    },

    OnReelSpinEnd:function(){
        this.ShowAntiEffect(false)
        this.notifyEvt(this._reelIdx);
    },

    notifyEvt(evt) {
        if(this.handler) {
            this.handler(evt);
        }
    }
});
