/**
 * 游戏流辅助类
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total)
            SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = false;
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal)
            SlotsFacade.mainPanel.showBg(2);
            SlotsFacade.soundMgr.playFreeBgm();
        }
        if(SlotsFacade.dm.energyData.state == 1) {
            await this.enterCollectGame();
        }
        if(SlotsFacade.dm.bonusData) {
            await this.enterBonusGame(true);
        }
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        // 收集能量
        await this.collectEnergy();

        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });

        await SlotsFacade.delayTime(0.5);
        // 进入收集游戏
        await this.enterCollectGame();
        // 进入bonus游戏
        await this.enterBonusGame();
        // 控制按钮
        if (SlotsFacade.dm.isTriggerFree()) {
            // SlotsFacade.bottomCmp.ShowBtnsByState("stoped");
            await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.triggerFreeCnt(), SlotsFacade.dm.isFistTriggerFree());
            if (SlotsFacade.dm.isFistTriggerFree()) {
                SlotsFacade.mainPanel.showSceneTransition(2);
                await SlotsFacade.delayTime(0.8);
                this.enterFreeGame();
            }
            await SlotsFacade.delayTime(1);
            SlotsFacade.slots.CanDoNextRound()
        } else if (cc.vv.gameData.hasFree()) {
            //await SlotsFacade.delayTime(1);
            SlotsFacade.slots.CanDoNextRound();
        } else if (cc.vv.gameData.isLastEndFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            await SlotsFacade.popup.showWinFreeGold(SlotsFacade.dm.getFreeWinCoin());
            SlotsFacade.mainPanel.showSceneTransition(2);
            await SlotsFacade.delayTime(0.5);
            this.enterNormalGame();
            await SlotsFacade.delayTime(0.5);
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
            SlotsFacade.slots.CanDoNextRound()
        } else {
            SlotsFacade.collectProgress.setEnterEnable(true);
            SlotsFacade.slots.CanDoNextRound()
        }
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame() {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.mainPanel.showBg(2);
        SlotsFacade.soundMgr.playFreeBgm();
        SlotsFacade.slots.changeSlots();
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = false;
        await SlotsFacade.delayTime(3.5);
    },

    /**
     * 进入普通游戏
     */
    enterNormalGame() {
        SlotsFacade.collectProgress.setEnterEnable(true);
        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(0);
        Global.SlotsSoundMgr.playNormalBgm();
        SlotsFacade.slots.clearFreeSymbols();
        SlotsFacade.slots.changeSlots();
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = true;
    },

    /**
     * 收集能量
     */
    async collectEnergy() {
        let progressData = SlotsFacade.dm.energyData.progressData;
        if (progressData && progressData.currCnt) {
            let items = SlotsFacade.slots.getSymbolsByServerIds(SlotsFacade.dm.getCollectSymbolIndexs());
            let posArr = [];
            items.forEach(v => {
                posArr.push(v.node.convertToWorldSpaceAR(cc.v2(0, 0)));
            });
            await SlotsFacade.collectProgress.collectEnergy(posArr, SlotsFacade.dm.getCollectPercent());
        }
    },

    /**
     * 进入地图游戏
     */
    async enterCollectGame() {
        let energyData = SlotsFacade.dm.energyData;
        if (energyData.state == 1 || (energyData.state == 2 && SlotsFacade.dm.isFistTriggerFree())) {
            SlotsFacade.topCmp.SetBackLobby(false);
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            await SlotsFacade.collectProgress.playCollectComplete();
            let ret = await new Promise(res => {
                SlotsFacade.collectProgress.setProgress(0);
                SlotsFacade.collectProgress.updateTailSpine(0);
                SlotsFacade.map.enterMap(false, res);
            });
            if(ret.winCoin) {
                let nWin = ret.winCoin;
                let nTotal = cc.vv.gameData.GetBottomScript().getCurrentWin();
                nTotal += ret.winCoin;
                await new Promise(res=>{
                    SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
                });
            }
        }
    },

    /**
     * 进入bonus游戏
     */
    async enterBonusGame(isReconnect) {
        if(!SlotsFacade.dm.bonusData) {
            return;
        }
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        if(!isReconnect) {
            await SlotsFacade.slots.playScatter(SlotsFacade.dm.getBonusIndexs());
        }
        await new Promise(res=>{
            SlotsFacade.bonusGame.enterGame(res, isReconnect);
        })
    }
 })