let grupNames = ["mini","minor","major","maxi","grand"]
let grupReelNum = [0,2,5,9,14]
cc.Class({
    extends: cc.Component,

    properties: {
        _callBack:null,  // 回调函数

        _data:null,

        panel:cc.Node,
        tipsNode:cc.Node,
        spine_win_board:sp.Skeleton,
        spine_footer:cc.Node,
        track_spine: cc.Node,
        jpNodes:[cc.Node],
        posArr:[cc.Node],
        _topAniNode:cc.Node,
        _topCollectAniNode:null,
        _grups:[],
        _hintList:[],
        _firstRoundGroup:0,  //最先转动的组
    },

    onDestroy() {
    },

    onLoad() {
        this._topCollectAniNode = cc.find("Canvas/safe_node/top_node");
        this._topCollectAniNode.zIndex = 1000;

        this._topAniNode = cc.find("top_ani",this.panel);
        this._initData();
        this._initReels();

        Global.AABB = this;
    },

    _initData() {
        this._data = {
            lastRoundReelsData:null, // 上轮旋转完成后 卷轴数据
            validReelLastIdx:0,      // 最后一个停止的列下标
            respData:null,   // 请求响应数据
        };
    },

    _initReels() {
        for (let i = 0; i < grupNames.length; i++) {
            const name = grupNames[i];
            let node = cc.find(name,this.panel)
            let script = node.getComponent("Interstellar_BonusGrup")
            script.initData(this._topAniNode,this._onGrupChange.bind(this),grupReelNum[i],i)
            this._grups.push(script)
        }
    },

    _onGrupChange(grupIdx) {
        if(grupIdx === this._data.validReelLastIdx){
            this.spinEnd();
        }else{
            if(this.getJackpotHint(grupIdx + 2)){
                this.playJpFlash(grupIdx + 2)
            }
        }
        let epicInfo = SlotsFacade.dm.bonusData;
        for (let i = 0; i < epicInfo.jackpotList.length; i++) {
            const jpId = epicInfo.jackpotList[i];
            if(jpId > grupIdx){
                this.playJpTitle(jpId,true)
                this.showWinJackPot(jpId)
                this.playWinJackPotEffect(jpId)
            }
        }
    },

    getJackpotHint(id){
        switch (id) {
            case 1:{   //mini
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element < 3){
                        return true
                    }
                }
                return false
            }
            case 2:{   //minor
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 2 && element < 6){
                        return true
                    }
                }
                return false
            }
            case 3:{   //major
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 5 && element < 10){
                        return true
                    }
                }
                return false
            }
            case 4:{   //maxi
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 9 && element < 15){
                        return true
                    }
                }
                return false
            }
            case 5:{   //grand
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 14 && element < 30){
                        return true
                    }
                }
                return false
            }
        }
    },

    showJiLi(id){
        switch (id) {
            case 1:{   //mini
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element < 3){
                        this._grups[id - 1].showJL(element)
                    }
                }
            }break
            case 2:{   //minor
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 2 && element < 6){
                        this._grups[id - 1].showJL(element)
                    }
                }
            }break
            case 3:{   //major
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 5 && element < 10){
                        this._grups[id - 1].showJL(element)
                    }
                }
            }break
            case 4:{   //maxi
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 9 && element < 15){
                        this._grups[id - 1].showJL(element)
                    }
                }
            }break
            case 5:{   //grand
                for (let i = 0; i < this._hintList.length; i++) {
                    const element = this._hintList[i];
                    if(element > 14 && element < 30){
                        this._grups[id - 1].showJL(element)
                    }
                }
            }break
        }
    },

    _initView(isReconnect) {
        let epicInfo = SlotsFacade.dm.bonusData;
        // 剩余次数
        this.showRestCnt(epicInfo.restCnt, true);
        for (let i = 0; i < this._grups.length; i++) {
            const grup = this._grups[i];
            grup.initView()
        }
        // jp框
        isReconnect = isReconnect || false;
        for(let i=0; i<this.jpNodes.length; i++) {
            let node = this.jpNodes[i];
            if(isReconnect) {
                node.y = this.posArr[i].y;
            }else {
                if(i==4) { //grand
                    node.y = this.posArr[i].y;
                }else if(i == 3) { // maxi
                    node.y = this.posArr[5].y;
                }else {
                    node.y = this.posArr[i].y - 320;
                }
                
            }
            for(let j=0; j<2; j++) {
                let spineTitle = node.getChildByName("spineTitle" + (j+1));
                spineTitle.getComponent(sp.Skeleton).setAnimation(0, "animation" + (5-i) + "_1", false);
            }
        }
        if(!isReconnect) {
            this.jpNodes[3].y = this.posArr[5].y;
        }else{
            for (let i = 0; i < epicInfo.jackpotList.length; i++) {
                const jpId = epicInfo.jackpotList[i];
                this.playJpTitle(jpId,true)
            }
        }
    },

    showRestCnt(cnt, isInit) {
        let tips = this.tipsNode.getChildByName("tips").getComponent("ImgSwitchCmp");
        if(cnt == 3) {
            tips.setIndex(2);
        }else if(cnt == 2){
            tips.setIndex(2);
        }else if(cnt == 1){
            tips.setIndex(1);
        }else {
            tips.setIndex(0);
        }

        let labelNode = this.tipsNode.getChildByName("label");
        if(cnt > 0) {
            labelNode.active = true;
            let labelCnt = labelNode.getChildByName("count").getComponent("ImgSwitchCmp");
            labelCnt.setIndex(cnt-1);
            if(cnt == 3 && !isInit) {
                let spine = labelNode.getChildByName("spine").getComponent(sp.Skeleton);
                spine.node.active = true;
                spine.setAnimation(0, "animation", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    spine.node.active = false;
                });
            }
        }else {
            labelNode.active = false;
        }
    },

    startMove() {
        this._firstRoundGroup = 0
        for (let i = 0; i < this._grups.length; i++) {
            const grup = this._grups[i];
            if(grup.startMove()){
                this._data.validReelLastIdx = i;
                if(this._firstRoundGroup === 0){
                    this._firstRoundGroup = i+1
                }
            }
        }
    },

    setSlotsResult() {
        for (let i = 0; i < this._grups.length; i++) {
            const grup = this._grups[i];
            grup.setSlotsResult()
        }
    },

    async spinEnd() {
        let epicInfo = SlotsFacade.dm.bonusData;
        this._data.lastRoundReelsData = epicInfo.items.concat();
        this._hintList = epicInfo.hintList
        this.showRestCnt(epicInfo.restCnt);
        await SlotsFacade.delayTime(1);
        if(epicInfo.restCnt > 0) {
            this.run();
        }else {
            this.startSettlement();
        }
    },

    async startSettlement() {
        let sum = 0;
        let data = this._data.respData;
        // 结算jp
        for(let i=0; i<data.jackpotValues.length; i++) {
            let val = data.jackpotValues[i];
            let type = data.epicInfo.jackpotList[i];
            SlotsFacade.soundMgr.playEffect("dialog_trigger_JP");
            await SlotsFacade.popup.showWinJPGold(type, val);
            sum += val;
            SlotsFacade.bottomCmp.SetWin(sum);
        }
        await SlotsFacade.delayTime(0.5);

        // 结算reel
        let endPos = cc.find('winBg/lbl_winNum_nor', SlotsFacade.bottomCmp.node).convertToWorldSpaceAR(cc.v2(0, 0));
        endPos = this._topCollectAniNode.convertToNodeSpaceAR(endPos);

        this.spine_footer.removeFromParent();
        this.spine_footer.parent = this._topCollectAniNode;
        this.spine_footer.position = endPos;
        this.spine_footer.active = false;

        for(let i=0; i<data.epicInfo.items.length; i++) {
            let val = data.epicInfo.items[i];
            if(val < 1) {
                continue;
            }
            sum += val;

            this.flyTrackSpine(i, ()=>{
                SlotsFacade.bottomCmp.SetWin(sum);
            });

            await SlotsFacade.delayTime(1);
        }
        cc.vv.gameData.AddCoin(sum)
        await SlotsFacade.popup.showWinBonusGold(sum);
        this.exitGame();
    },

    flyTrackSpine (reelIdx, callback) {
        SlotsFacade.soundMgr.playEffect("fly");

        // spine_flash

        // 结算reel
        let endNode = cc.find('winBg/lbl_winNum_nor', SlotsFacade.bottomCmp.node);
        let endPos = endNode.convertToWorldSpaceAR(cc.v2(0, 0));
        endPos = this._topCollectAniNode.convertToNodeSpaceAR(endPos);

        let symbol = this.getSymbolByIndex(reelIdx)
        symbol.playWinFlash();

        let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
        startPos = this._topCollectAniNode.convertToNodeSpaceAR(startPos);

        let spine = cc.instantiate(this.track_spine);
        spine.active =true;
        spine.parent = this._topCollectAniNode;
        spine.x = startPos.x;
        spine.y = startPos.y;

        spine.angle = this.getAngle(symbol.node, endNode);
        spine.scaleY = this.getDistance(symbol.node, endNode)/(spine.height/2);

        spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        spine.getComponent(sp.Skeleton).timeScale = 0.7;
        spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
            spine.removeFromParent();
            if (callback) callback();

            this.spine_footer.active = true;
            this.spine_footer.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            this.spine_footer.getComponent(sp.Skeleton).setCompleteListener(()=>{
                this.spine_footer.active = false;
            });
        });
    },

    getSymbolByIndex(idx){
        let grupIdx = 0
        let celIdx = idx + 1
        for (let i = 2; i < 6; i++) {
            const num = i;
            if(celIdx > num){
                celIdx -= num
                grupIdx++
            }else{
                break
            }
        }
        // cc.log("idx:",idx,grupIdx,celIdx)
        return this._grups[grupIdx]._reels[celIdx - 1].GetSymbolByRow(0)
    },

    getAngle (node1, node2) {
        let pos1 = node1.convertToWorldSpaceAR(cc.v2(0,0));
        let pos2 = node2.convertToWorldSpaceAR(cc.v2(0,0));
        let o = pos1.x-pos2.x;
        let a = pos1.y-pos2.y;
        let at = Math.atan(o / a) * 180 / Math.PI;
        if (a < 0) {
            if (o < 0)
                at = 180 + Math.abs(at);
            else
                at = 180 - Math.abs(at);
        }
        // at-= 90  //物体初始是水平摆放
        return -at;
    },

    getDistance (node1, node2) {
        let pos1 = node1.convertToWorldSpaceAR(cc.v2(0,0));
        let pos2 = node2.convertToWorldSpaceAR(cc.v2(0,0));
        return Math.abs(pos1.sub(pos2).mag());
    },

    //播放闪电
    playJpTitle (jpIdx, bPlay) {
        let jpNode = this.jpNodes[jpIdx - 1];

        //播放闪电
        let spineTitle1 = jpNode.getChildByName("spineTitle1");
        if (bPlay)
            spineTitle1.getComponent(sp.Skeleton).setAnimation(0, "animation" + (6- jpIdx), true);
        else
            spineTitle1.getComponent(sp.Skeleton).setAnimation(0, "animation" + (6- jpIdx) + "_1", false);

        let spineTitle2 = jpNode.getChildByName("spineTitle2");
        if (bPlay)
            spineTitle2.getComponent(sp.Skeleton).setAnimation(0, "animation" + (6- jpIdx), true);
        else
            spineTitle2.getComponent(sp.Skeleton).setAnimation(0, "animation" + (6- jpIdx) + "_1", false);
    },

    //播放闪电
    async playJpFlash (jpIdx) {
        let jpNode = this.jpNodes[jpIdx - 1];

        let towin = cc.find("towin",jpNode)
        towin.active = true
        let light1 = cc.find("light1",towin)
        light1.active = true
        let light2 = cc.find("light2",towin)
        light2.active = true
        let end = cc.find("end",towin)
        end.active = false
        //播放闪电
        light1.active = true
        light2.active = true
        light2.getComponent(sp.Skeleton).setCompleteListener(()=>{
            light1.active = false
            light2.active = false
            light2.getComponent(sp.Skeleton).setCompleteListener(null)
        })
        await SlotsFacade.delayTime(0.5)
        this.showJiLi(jpIdx)
        end.active = true
        end.getComponent(sp.Skeleton).setCompleteListener(()=>{
            end.active = false
            end.getComponent(sp.Skeleton).setCompleteListener(null)
        })
    },

    playWinJackPotEffect(jpIdx){
        let jpNode = this.jpNodes[jpIdx - 1];
        let winJackpot = cc.find("winJackpot",jpNode)
        winJackpot.active = true
        let winJackpotSp = winJackpot.getComponent(sp.Skeleton)
        winJackpotSp.setCompleteListener(()=>{
            winJackpot.active = false
            winJackpotSp.setCompleteListener(null)
        })
    },

    showWinJackPot(jpIdx){
        let win_jp_loop = cc.find("Canvas/safe_node/LMSlots_PrizePool_1/prizePool_"+grupNames[jpIdx-1]+"/spine");
        win_jp_loop.active = true;
    },

    hideWinJackPot(){
        for (let i = 0; i < 5; i++) {
            let win_jp_loop = cc.find("Canvas/safe_node/LMSlots_PrizePool_1/prizePool_"+grupNames[i]+"/spine");
            win_jp_loop.active = false;
        }
    },

    //播放白色流光边框
    playJpWhiteFrame (jpIdx, bPlay) {
        //播放蓝色边框流光
        let spine_win_board = cc.find("panel/spine_win_board", this.node);
        spine_win_board.getComponent(sp.Skeleton).setAnimation(0, "animation" + (6- jpIdx), true);
        spine_win_board.active = bPlay;
    },

    async run() {
        let epicInfo = SlotsFacade.dm.bonusData;
        // 更新次数
        this.showRestCnt(epicInfo.restCnt-1);
        // 开始转动
        this.startMove();
        // 请求消息
        SlotsFacade.dm.reqSubGame({rtype:2});
    },

    async onSpin(msg){
        this._data.respData = msg.data;
        SlotsFacade.dm.bonusData = msg.data.epicInfo;
        await SlotsFacade.delayTime(1);

        // 设置结果
        this.setSlotsResult();
        // 设置列停止间隔
        let reelTime = 0;
        let reelStopInterv = 0.2;
        let currRoundItems = SlotsFacade.dm.bonusData.items;
        for (let i = 0; i < this._grups.length; i++) {
            const grup = this._grups[i];
            for (let j = 0; j < grup._reels.length; j++) {
                const reel = grup._reels[j];
                let val = this._data.lastRoundReelsData[grup._grupIndex + j];
                if(val == -1) {
                    reel.StopMove(reelTime);
                    reelTime += reelStopInterv;
                }
            }
        }
        this.showAddDelayTime()
        if(this.getJackpotHint(this._firstRoundGroup)){
            this.playJpFlash(this._firstRoundGroup)
        }
    },

    showAddDelayTime(){
        for (let i = 1; i < 6; i++) {
            if(this.getJackpotHint(i)){
                for (let j = i-1; j < this._grups.length; j++) {
                    const grup = this._grups[j];
                    grup.AddDelayTime(2)
                }
            }
        }
    },

    /**
     * 进入游戏
     * @param {*} callBack 
     * @param {*} isReconnect 
     */
    async enterGame(callBack, isReconnect) {
        this._callBack = callBack;
        if(!isReconnect) {
            await new Promise(res=>{
                SlotsFacade.popup.showStartBonus(()=>{
                    res();
                });
            });
        }
        Global.SlotsSoundMgr.playBgm("111xjs_Freesound");
        this.panel.active = true;
        SlotsFacade.mainPanel.charactor.active = false;
        SlotsFacade.mainPanel.slots.active = false;
        this._initData();
        this._data.lastRoundReelsData = SlotsFacade.dm.bonusData.items.concat();
        this._initView(isReconnect);
        if(isReconnect) {
            this._hintList = SlotsFacade.dm.bonusData.hintList
            await SlotsFacade.delayTime(0.5);
            this.run();
        }else {
            this._hintList = []
            await this.playShowAni();
            this.run();
        }
    },

    /**
     * 出场动画
     */
    async playShowAni() {
        SlotsFacade.soundMgr.playEffect("reel_raise");
        // 移动前3个
        for(let i=0; i<3; i++) {
            cc.tween(this.jpNodes[i])
                .to(0.5, {y:this.posArr[i].y})
                .delay(0.15)
                .start();
        }
        await SlotsFacade.delayTime(0.7);
        // 移动maxi
        this.jpNodes[3].y = this.posArr[3].y;
        await SlotsFacade.delayTime(0.1);

        // 缩放 jpNode
        let spaceTime = 0.15;
        for(let i=0; i<this.jpNodes.length; i++) {
            let node = this.jpNodes[i];
            cc.tween(node)
                .delay(spaceTime*i)
                .call(()=>{
                    SlotsFacade.soundMgr.playEffect("map_close");
                })
                .to(0.3, {scale:1.2})
                .to(0.2,{scale:1})
                .start();

            for(let j=0; j<2; j++) {
                let title = node.getChildByName("spineTitle" + (j+1));
                title.getComponent(sp.Skeleton).setAnimation(0, "animation" + (5- i), false);
                title.getComponent(sp.Skeleton).addAnimation(0, "animation" + (5- i) + "_1", false);
                // cc.tween(title)
                //     .delay(spaceTime*i)
                //     .to(0.4, {scale:1}, {easing:"backOut"})
                //     .start();
            }
        }
        await SlotsFacade.delayTime(1);
    },

    async exitGame() {
        SlotsFacade.mainPanel.showSceneTransition(1,async ()=>{
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(SlotsFacade.bottomCmp.getCurrentWin(),SlotsFacade.bottomCmp.getCurrentWin(),true, res);
            });
            if(this._callBack) {
                this._callBack();
            }
        });
        await SlotsFacade.delayTime(0.5);
        this.hideWinJackPot()
        Global.SlotsSoundMgr.playNormalBgm(true);
        this.panel.active = false;

        SlotsFacade.mainPanel.charactor.active = true;
        SlotsFacade.mainPanel.slots.active = true;
    }
});
