/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        energyData  : null,   // 能量数据
        bonusData   : null,   // epic link feature
    },

    init(deskInfo,gameId,gameJackpot) {
        this._super(deskInfo,gameId,gameJackpot);
        this.energyData = this._deskInfo.mapInfo;
        this.bonusData = this._deskInfo.epicInfo;
    },

    //注册msg
    RegisterMsg(){
        this._super()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, this);
    },
    UnregisterMsg(){
        this._super()
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, false, this);
    },

    OnRcvNetSpine:function(msg){
        this._super(msg);
        if(msg.code == 200){
            this.energyData = msg.mapInfo;
            this.bonusData = msg.epicInfo;
        }
    },

    SetSubGameData:function(data){
        this._subGame = data
    },

    GetSubGameData:function(){
        return this._subGame
    },

    getSpinData() {
        return this._gameInfo;
    },

    /**
     * 处理卷轴结果替换相应id
     * @param {*} cards 
     */
    processResultCards(cards) {
        let result = cards.concat();
        let row = 8;
        let col = 5;
        let Cfg = this.getGameCfg();
        let wildIdMap = {
            "1":2001,
            "101":2101,
            "102":2102
        };
        for(let i=0; i<cards.length; i++) {
            let c = cards[i];
            if(!Cfg.isWild(c)) {
                continue;
            }
            let crrRow = Math.floor(i/col); // 当前所处的行 0-7
            let upperIsScatter = false; // 这张牌上面是否有scatter
            let downIsScatter = false;  // 这张牌下面是否有scatter
            if(crrRow == 0) { // 如果在第一行上面必然没有scatter
                upperIsScatter = false;
            }else {  
                upperIsScatter = Cfg.isWild(cards[i-col]);
            }
            if(crrRow == row-1) {
                downIsScatter = false;// 如果在最后一行,下面必然没有scatter
            }else {
                downIsScatter = Cfg.isWild(cards[i+col]);
            }

            if(crrRow == 0) {
                if(downIsScatter) {
                    result[i] = wildIdMap[c];
                }
            }else if(crrRow == 4) {
                if(upperIsScatter) {
                    result[i] = wildIdMap[c];
                }
            }else {
                if(upperIsScatter) {
                    result[i] = wildIdMap[c];
                }
            }
        }
        return result;
    },

    /**
     * 获取slots个数
     */
    getSlotsCnt() {
        if(this.energyData.state == 2) {
            return this.getGameCfg().mapCfg[this.energyData.currId.toString()].slot.cnt;
        }else {
            return 1;
        }
    },
    ////////////////////////免费相关///////////////////////
    /**
     * 免费游戏重免费卷轴相关数据
     */
    getAdventureInSpace() {
        if(this._gameInfo) {
            return this._gameInfo.AdventureInSpace;
        }
        return this._deskInfo.AdventureInSpace;
    },
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let freeResult = this._gameInfo.freeResult;
        if(freeResult && freeResult.triFreeCnt  && freeResult.freeInfo && freeResult.freeInfo.freeCnt) {
           return freeResult.freeInfo.freeCnt;
        }
        return 0;
    },
    
    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 免费游戏赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this._gameInfo.freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    getBonusIndexs() {
        if(!this.bonusData) {
            return [];
        }
        let ret = [];
        let scatterId = this.getGameCfg().scatterId;
        let cards = this.getSpinData().resultCards;
        for(let i=0; i<cards.length; i++) {
            let c = cards[i];
            if(c == scatterId) {
                ret.push(i+1);
            }
        }
        return ret;
    },

    ///////////////////////////收集相关/////////////////
    
    /**
     * 收集游戏最小下注
     * @returns {{singleBet: number, mult: number, line: BonieClyde_GameData._deskInfo.line, isMax: boolean}}
     */
    getMinCollectBet() {
        // if(this.energyData.needBetIdx > this.canBetList.length) {
        //     return null;
        // }
        // let ret = {
        //     singleBet:0,    // 单线下注额
        //     mult:0,         // 单线下注额 在可下注列表中的下标
        //     line:this.currLine, // 线数
        //     isMax:false          // 是否是最大值
        // };
        // let index = this.colection.needBet - 1;
        // ret.singleBet = this.canBetList[index];
        // ret.mult = index;
        // return ret;
    },

    /**
     * 获取当前收集进度
    */
    getCollectPercent() {
        if(!this.energyData || !this.energyData.progressData) {
            return 0;
        }
        let percent = this.energyData.progressData.totalCnt / this.energyData.progressData.needCnt;
        percent = Math.min(1, percent);
        percent = Math.max(0, percent);
        return percent;
    },

    /**
     * 获取结果中收集图标得的下标
     */
    getCollectSymbolIndexs() {
        let cards = this._gameInfo.resultCards
        if(!cards || cards.length < 1) {
            return [];
        }
        let ret = [];
        cards.forEach((v, i)=>{
            if(this.getGameCfg().isEnergyId(v)) {
                ret.push(i+1);
            }
        });
        return ret;
    },

    /**
     * 当前下注是否达到收集的条件
     */
    canCollect() {
        return this.GetBetIdx() >= this.getDeskInfo().needBet;
    },

    /**
     * 请求子游戏数据51
     * @param param
     */
    reqSubGame(param) {
        let req = {
            c:MsgId.SLOT_SUBGAME_DATA,
            gameid:this._gameId,
            data:param
        };
        cc.vv.NetManager.send(req, true);
    },

    onResp(msg){
        console.log("<<<< reqSubGame-resp: ", msg);
        if(msg.data.rtype === 2){
            SlotsFacade.bonusGame.onSpin(msg)
        }else{
            SlotsFacade.map._mapWheel.onSpinWheel(msg)
        }
    },

    /**
     * 获取cards列数据
     * @param {*} colIndex 0~4
     */
    getColCards(colIndex) {
        let data = this._gameInfo.resultCards;
        let ret = [];
        let col = 5;
        let row = 4;
        for(let i=0; i<row; i++) {
            ret.push(data[colIndex + i*col]);
        }
        return ret;
    },
});
