/**
 * 判断id 是否为wild
 * @param {number} id 
 */
Cfg.isWild = function(id) {
    return id == 1;
};

/**
 * 判断是否是收集能量的图标
 * @param {*} id 
 */
Cfg.isEnergyId = function(id) {
    return id == 2 || id == 3;
};

